package com.harvestflow.api.controller;
import com.harvestflow.api.dto.delivery.*; import com.harvestflow.api.security.SecurityUser; import com.harvestflow.api.service.DeliveryService; import jakarta.validation.constraints.NotBlank; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/deliveries") @RequiredArgsConstructor public class DeliveryController { private final DeliveryService service;
 @GetMapping("/assigned") @PreAuthorize("hasRole('PICKUP_PERSON')") public List<DeliveryAssignmentResponse> assigned(@AuthenticationPrincipal SecurityUser p){return service.assignedTo(p.getUser());}
 @PostMapping("/{orderId}/pickup") @PreAuthorize("hasRole('PICKUP_PERSON')") public DeliveryAssignmentResponse pickup(@PathVariable UUID orderId,@AuthenticationPrincipal SecurityUser p){return service.confirmPickup(orderId,p.getUser());}
 @PostMapping("/{orderId}/reach-buyer") @PreAuthorize("hasRole('PICKUP_PERSON')") public DeliveryAssignmentResponse reach(@PathVariable UUID orderId,@AuthenticationPrincipal SecurityUser p){return service.reachBuyer(orderId,p.getUser());}
 @PostMapping("/{orderId}/complete") @PreAuthorize("hasRole('PICKUP_PERSON')") public DeliveryAssignmentResponse complete(@PathVariable UUID orderId,@RequestParam @NotBlank String otp,@AuthenticationPrincipal SecurityUser p){return service.complete(orderId,otp,p.getUser());}
 @PostMapping("/{orderId}/assign") @PreAuthorize("hasRole('ADMIN')") public DeliveryAssignmentResponse assign(@PathVariable UUID orderId,@RequestParam @NotBlank String deliveryBoyUsername,@AuthenticationPrincipal SecurityUser p){return service.assign(orderId,deliveryBoyUsername,p.getUser());}
 @PostMapping("/{orderId}/otp") @PreAuthorize("hasAnyRole('FARMER','FPO','CONSUMER','BULK_BUYER')") public DeliveryOtpResponse otp(@PathVariable UUID orderId,@AuthenticationPrincipal SecurityUser p){String value=service.generateOtp(orderId,p.getUser());return new DeliveryOtpResponse(orderId.toString(),value,600);}
 @GetMapping("/{orderId}/receipt") @PreAuthorize("hasAnyRole('FARMER','FPO','CONSUMER','BULK_BUYER')") public ReceiptResponse receipt(@PathVariable UUID orderId,@AuthenticationPrincipal SecurityUser p){return service.receipt(orderId,p.getUser());}
}
